"""Self-contained offline review of synthetic terrain, placements and all quest text."""
import base64
import json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
raw=(ROOT/"shared/data/ai-world-v1.json").read_text(encoding="utf8")
atlas=base64.b64encode((ROOT/"client/assets/tiles/original_tiles.png").read_bytes()).decode()
catalog=json.loads(raw)
drafts=[json.loads(p.read_text(encoding='utf8')) for p in sorted((ROOT/'analysis/ai-generated/map-designs').glob('*.json'))]
references={p.name:'data:image/png;base64,'+base64.b64encode(p.read_bytes()).decode() for p in (ROOT/'analysis/references/map-screenshots').glob('*.png')}
baseline_path=ROOT/'analysis/ai-generated/layout-review-before-v4.json'
baseline=json.loads(baseline_path.read_text(encoding='utf8'))['maps'] if baseline_path.exists() else []
monsters=[r for m in catalog['maps'] for r in m['residents'] if r['kind']!='npc']
keys={p["art"] for m in [*catalog["maps"],*drafts,*baseline] for p in m["scenery"]}|{r["art"] for m in [*catalog["maps"],*baseline] for r in m["residents"]}
art={}
for key in sorted(keys):
    info=json.loads((ROOT/"client/assets/data/actors"/(key+".json")).read_text(encoding="utf8"))
    info["src"]="data:image/png;base64,"+base64.b64encode((ROOT/"client"/info["texture"].removeprefix("res://")).read_bytes()).decode()
    art[key]=info
pin="data:image/png;base64,"+base64.b64encode((ROOT/"client/assets/ui/portal_tile.png").read_bytes()).decode()
html='''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>蜀山 · AI生成地图与任务审核</title>
<style>*{box-sizing:border-box}body{margin:0;background:#10252a;color:#f2e7c4;font:15px/1.7 system-ui,sans-serif}header{padding:28px max(24px,5vw);background:#18383c;border-bottom:1px solid #917640}h1{margin:0;font-size:26px}p{margin:7px 0}small{color:#b6c8bc}.tools{display:flex;gap:12px;padding:18px max(24px,5vw);position:sticky;top:0;background:#10252af0;z-index:2}input,select,button{font:inherit;border:1px solid #8b7848;background:#244348;color:#f6e7b9;padding:9px 14px;border-radius:4px}input{flex:1;min-width:100px}main{display:grid;grid-template-columns:repeat(auto-fill,minmax(245px,1fr));gap:18px;padding:0 max(24px,5vw) 40px}article{border:1px solid #496464;background:#173237;padding:14px;border-radius:8px;cursor:pointer}h2{font-size:17px;margin:8px 0 0}canvas{width:100%;image-rendering:pixelated;background:#081b22}article:hover{border-color:#e1bd5b}.badge{color:#f7cf73;font-size:12px}dialog{background:#173237;color:#f2e7c4;border:1px solid #bf9e4c;border-radius:8px;width:min(1000px,95vw);max-height:92vh;padding:24px}dialog::backdrop{background:#000a}.detail{display:grid;grid-template-columns:1fr 1fr;gap:24px}.task{padding:14px;background:#203e40;border:1px solid #4f6560;margin:12px 0}ul{padding-left:20px}#close{float:right}#count{margin-left:auto;white-space:nowrap}@media(max-width:650px){.detail{grid-template-columns:1fr}.tools{flex-wrap:wrap}#count{font-size:12px}}a{color:#f3ce74}</style>
<header><h1>蜀山驿路 · AI生成内容审核</h1><p>214 张地图 · 642 个三段任务 · __NPC_COUNT__ 个 NPC / 调查点 · __MONSTER_COUNT__ 个怪物刷新位置（214图合计） · __MONSTER_ART_COUNT__ 套怪物外形</p><small>地名、等级参考原包；147条怪物分布参考用户表格，其余按地域补足。布局、NPC位置、剧情、战斗数值与奖励均为 AI 生成。不是恢复出的原版地图。<br>怪物外形使用原包素材，由AI按外形推定名称对应，尚无原始ID映射。同名地图按原编号保留；副本、帮战与礼堂场景按探索任务演示。</small><h2>独立地图方案 · 未接入游戏</h2><p>血魔祭坛先保存副本设计；天丢谷暂存局部参考，不占用原地图编号。</p><div id="drafts" style="display:flex;gap:12px;flex-wrap:wrap"></div></header>
<section id="comparison" style="padding:24px max(24px,5vw)"><h2>修改前后 · 地形、人物与传送口</h2><p>修正原包水面中心/岸角对应；按表格补齐人物，缺项按地点用途生成。每图人数随城镇、营地、野外用途变化。蓝色回纹砖是传送口，并非人物出生点；已取消每图强制4处。</p><div id="comparisons"></div></section><div class="tools"><input id="search" placeholder="搜索地名、NPC、任务或原地图编号"><select id="biome"><option value="">全部地貌</option></select><select id="layout"><option value="">全部场景布局</option></select><span id="count"></span></div><main id="maps"></main>
<dialog id="modal"><button id="close">关闭</button><h2 id="title"></h2><p class="badge">AI生成布局 · 原包场景美术 · 黄点：人物进入落点（每图1处） · 青色回纹砖：地图传送口</p><label>怪物原生姿势 <select id="motion"><option value="idle">待机</option><option value="walk">行走</option><option value="attack">攻击</option><option value="hurt">受击</option></select></label><div class="detail"><div><canvas id="terrain" width="512" height="512"></canvas><p id="description"></p><div id="npcs"></div><h3>本图怪物与来源</h3><div id="monsters"></div></div><div id="quests"></div></div></dialog>
<script>const DATA=__DATA__;const DRAFTS=__DRAFTS__;const BASELINE=__BASELINE__;const REFS=__REFS__;const ART=__ART__;const texture=new Image();texture.src='data:image/png;base64,__ATLAS__';const pin=new Image();pin.src='__PIN__';const images={};const ready=[texture,pin].map(im=>new Promise(r=>im.onload=r));for(const [key,info] of Object.entries(ART)){const im=new Image();ready.push(new Promise(r=>im.onload=r));im.src=info.src;images[key]=im;}
const $=s=>document.getElementById(s);const maps=DATA.maps;function text(parent,tag,value){let n=document.createElement(tag);n.textContent=value;parent.append(n);return n}
function sprite(c,key,x,y,z,frame){const a=ART[key],im=images[key];if(!a||!im.complete)return;const f=frame??a.playback?.idle?.[0]?.[0]??0;c.drawImage(im,f%a.columns*a.width,Math.floor(f/a.columns)*a.height,a.width,a.height,(x+a.origin[0])*z,(y+a.origin[1])*z,a.width*z,a.height*z)}
function pose(key,time,mode='idle'){const seq=ART[key]?.playback?.[mode];if(!seq?.length)return 0;let t=time/(mode==='idle'?1000/6:100),sum=seq.reduce((n,s)=>n+Math.max(1,s[1]),0);t%=sum;for(const [frame,duration] of seq){if(t<Math.max(1,duration))return frame;t-=Math.max(1,duration)}return seq[0][0]}
function caption(c,value,x,y,color){c.font='13px sans-serif';c.textAlign='center';c.lineWidth=3;c.strokeStyle='#10252a';c.strokeText(value,x,y);c.fillStyle=color;c.fillText(value,x,y)}
function draw(canvas,m,labels=false,time=0){let c=canvas.getContext('2d');c.imageSmoothingEnabled=false;let s=canvas.width/32,z=s/16;for(let i=0;i<1024;i++){let t=m.tiles[i];c.drawImage(texture,t%32*16,Math.floor(t/32)*16,16,16,i%32*s,Math.floor(i/32)*s,s,s)}const pads=[...m.exits.flatMap(g=>g.cells??[g.cell]),...(m.portal_previews??[])];for(const point of pads)c.drawImage(pin,point[0]*s,point[1]*s,s,s);if(labels&&m.runtime_enabled!==false){const x=(m.spawn[0]+.5)*s,y=(m.spawn[1]+.5)*s;c.beginPath();c.arc(x,y,3,0,Math.PI*2);c.fillStyle='#ffe36c';c.fill()}const layers=[...m.scenery.map(p=>({...p,resident:false})),...m.residents.map(r=>({...r,x:r.cell[0]*16+8,y:r.cell[1]*16+8,resident:true}))].sort((a,b)=>a.y-b.y);for(const p of layers){sprite(c,p.art,p.x,p.y,z,p.resident?pose(p.art,time,labels&&p.kind!=='npc'?$('motion').value:'idle'):undefined);if(labels&&p.resident){const x=p.x*z,y=(p.y-65)*z;caption(c,p.name,x,y,p.kind==='npc'?'#c2f7f4':'#ffb8a8');if(p.service_label)caption(c,p.service_label,x,y-17,'#ffe390')}}if(labels){for(const p of m.design_points??[]){const x=(p.cell[0]+.5)*s,y=(p.cell[1]+.5)*s;c.strokeStyle='#ddad54';c.setLineDash([4,3]);c.strokeRect(x-20,y-12,40,24);c.setLineDash([]);caption(c,p.name,x,y-18,'#ffe390')}}}
for(let label of [...new Set(maps.map(m=>m.biome_name))]){let o=document.createElement('option');o.value=label;o.textContent=label;$('biome').append(o)}
for(let label of [...new Set(maps.map(m=>m.layout_name))]){let o=document.createElement('option');o.value=label;o.textContent=label;$('layout').append(o)}
function render(){let q=$('search').value.trim(),b=$('biome').value,l=$('layout').value,chosen=maps.filter(m=>(!b||m.biome_name===b)&&(!l||m.layout_name===l)&&(!q||JSON.stringify([m.name,m.original_map_id,m.residents.map(r=>r.name),m.quests.map(r=>r.name)]).includes(q)));$('maps').replaceChildren();$('count').textContent=chosen.length+' / 214 张';for(let m of chosen){let a=document.createElement('article'),cv=document.createElement('canvas');cv.width=cv.height=256;a.append(cv);draw(cv,m);text(a,'h2',m.name+' #'+String(m.original_map_id).padStart(3,'0'));text(a,'small',m.layout_name+' · '+m.level_min+'～'+m.level_max+'级');text(a,'div',m.residents.filter(r=>r.kind==='npc').length+' 位NPC · '+m.residents.filter(r=>r.kind!=='npc').length+' 个怪物刷新点 · '+m.exits.length+' 处地图传送口');text(a,'div','AI生成').className='badge';a.onclick=()=>show(m);$('maps').append(a)}}
let selected=null;function show(m){selected=m;const draft=m.runtime_enabled===false;$('modal').querySelector('.badge').textContent=draft?'局部参考 + AI设计 · 未接入游戏 · 虚线为预留位置':'AI生成布局 · 原包场景美术 · 黄点：人物进入落点（每图1处） · 青色回纹砖：地图传送口';$('title').textContent=m.name+(draft?' · 设计稿 #未分配':' #'+m.original_map_id)+' · '+m.layout_name;$('description').textContent=m.description;draw($('terrain'),m,true);$('npcs').replaceChildren();text($('npcs'),'p',draft?'未接入运行地图，无活动NPC或副本规则':'NPC与调查点：'+m.residents.filter(r=>r.kind==='npc').map(r=>r.name).join('、'));text($('npcs'),'small',draft?'虚线框是设计预留；地砖仅演示，不触发传送。':'前往方式：游戏「地图 → AI生成·驿路目录」选择目的地，角色会先走近驿石。');$('quests').replaceChildren();for(let q of m.quests){let box=document.createElement('section');box.className='task';text(box,'strong',q.name+' · AI生成');text(box,'p',q.description);let list=document.createElement('ul');for(let o of q.objectives)text(list,'li',o.text+' ×'+o.count);box.append(list);text(box,'small','接取等级 '+q.min_level+' · 奖励 '+q.gold+'铜钱 / '+q.xp+'修为'+(q.prerequisite?' · 需完成前章':''));$('quests').append(box)}if(m.screenshot_reference){text($('quests'),'h3','用户截图 · 局部参考');text($('quests'),'p',m.screenshot_reference.scope);for(const file of m.screenshot_reference.files){const im=document.createElement('img');im.src=REFS[file];im.alt=file;im.style.cssText='display:block;max-width:100%;max-height:420px;object-fit:contain;image-rendering:pixelated;margin:12px 0';$('quests').append(im)}if(m.screenshot_reference.screenshot_exit_ids)text($('quests'),'small','截图10022 / 10023按该版本记录；当前原包仍使用22 / 23。NPC名称与职能有依据，专用人物造型和原版服务功能尚未恢复。')}if(draft)text($('quests'),'p',m.asset_note);$('modal').showModal()}
let last=0;function animate(t){if(selected&&$('modal').open&&t-last>90){last=t;draw($('terrain'),selected,true,t)}requestAnimationFrame(animate)}requestAnimationFrame(animate);
function populateMonsters(m){$('monsters').replaceChildren();text($('monsters'),'p',(m.runtime_enabled===false?'传送仅为设计预留：':'人物进入落点：1处（黄点）；地图传送口：'+m.exits.length+'处（同一条地砖阵计1处）。目的地：')+m.exits.map(g=>g.name+' ['+g.cell.join(',')+']').join('、'));for(const r of m.residents.filter(r=>r.kind!=='npc')){const row=document.createElement('div');row.style.cssText='border-top:1px solid #496464;padding:12px 0;display:flex;gap:12px';const icon=document.createElement('canvas');icon.width=140;icon.height=110;icon.style.cssText='width:110px;height:87px;flex:none';const c=icon.getContext('2d');c.imageSmoothingEnabled=false;sprite(c,r.art,70,100,1,pose(r.art,0));row.append(icon);const body=document.createElement('div');text(body,'strong',r.name+' · '+r.level+'级'+(r.kind==='boss'?' · 镇守目标':''));text(body,'div','气血 '+r.hp+' / 攻击 '+r.attack+' / 防御 '+r.defense);text(body,'small',r.reference.source+(r.reference.source_row?' · 表格第'+r.reference.source_row+'行'+r.reference.source_columns+'列':''));text(body,'div',r.art);text(body,'small',r.reference.appearance+'；战斗数值为AI临时设计');row.append(body);$('monsters').append(row)}}
function populateNPCs(m){if(!m.residents.some(r=>r.kind==='npc'))return;text($('npcs'),'h3','驻地人物 · '+m.residents.filter(r=>r.kind==='npc').length+'位');for(const r of m.residents.filter(r=>r.kind==='npc')){const row=document.createElement('section');row.style.cssText='padding:10px 0;border-top:1px solid #496464';text(row,'strong',r.name+' · '+(r.service_label??'驻地人物'));text(row,'p',r.dialogue??'');text(row,'small',(r.npc_reference?.source??'AI生成')+(r.npc_reference?.source_row?' · 原表第'+r.npc_reference.source_row+'行':'')+'；外形与位置为AI匹配');$('npcs').append(row)}}
function comparisons(){for(const old of BASELINE){const m=maps.find(m=>m.map_id===old.map_id),section=document.createElement('section');text(section,'h3',m.name+' #'+m.original_map_id);const grid=document.createElement('div');grid.style.cssText='display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:18px;max-width:1050px';for(const [label,map] of [['修改前',old],['修改后',m]]){const box=document.createElement('div');text(box,'strong',label+' · '+map.residents.filter(r=>r.kind==='npc').length+'位NPC · '+map.exits.length+'处传送口');const cv=document.createElement('canvas');cv.width=cv.height=512;cv.dataset.map=map.map_id;cv.dataset.version=label;cv.style.cursor='pointer';draw(cv,map);cv.onclick=()=>show(m);box.append(cv);grid.append(box)}section.append(grid);$('comparisons').append(section)}}
const showBase=show;show=function(m){showBase(m);populateMonsters(m);populateNPCs(m)};
$('close').onclick=()=>$('modal').close();$('search').oninput=render;$('biome').onchange=render;$('layout').onchange=render;Promise.all(ready).then(()=>{render();comparisons();for(const m of DRAFTS){const button=document.createElement('button');button.className='draft';const cv=document.createElement('canvas');cv.width=cv.height=256;cv.style.width='180px';button.append(cv);text(button,'div',m.name+' · 未接入');draw(cv,m);button.onclick=()=>show(m);$('drafts').append(button)}const requested=new URLSearchParams(location.search).get('design');if(requested){const m=DRAFTS.find(m=>m.design_id===requested);if(m)show(m)}});
</script></html>'''
out=ROOT/"work/ai-world-review/index.html"
out.parent.mkdir(parents=True,exist_ok=True)
out.write_text(html.replace('__NPC_COUNT__',str(sum(r['kind']=='npc' for m in catalog['maps'] for r in m['residents']))).replace('__MONSTER_COUNT__',str(len(monsters))).replace('__MONSTER_ART_COUNT__',str(len({r['art'] for r in monsters}))).replace('__DATA__',raw.replace('</','<\\/')).replace('__BASELINE__',json.dumps(baseline,ensure_ascii=False).replace('</','<\\/')).replace('__DRAFTS__',json.dumps(drafts,ensure_ascii=False).replace('</','<\\/')).replace('__REFS__',json.dumps(references)).replace('__ATLAS__',atlas).replace('__ART__',json.dumps(art,ensure_ascii=False).replace('</','<\\/')).replace('__PIN__',pin),encoding='utf8')
print(out)
